def downgrade() -> None:
    # Seed data only touches the global (care_home_id IS NULL) template rows
    # introduced by migration 0013. Deliberately NOT deleting anything from
    # care_events / care_event_options / care_event_measurements here: if a
    # carer has already recorded real events against one of these seed
    # templates, the foreign key from care_events.template_id will correctly
    # block this downgrade rather than silently destroying clinical records.
    # That failure is the intended behaviour, not a bug to work around.
    op.execute("DELETE FROM care_template_measurements WHERE care_home_id IS NULL;")
    op.execute("DELETE FROM care_template_options WHERE care_home_id IS NULL;")
    op.execute("DELETE FROM care_template_sections WHERE care_home_id IS NULL;")
    op.execute("DELETE FROM care_templates WHERE care_home_id IS NULL;")
    op.execute("DELETE FROM care_categories;")
